import { Component, OnInit } from '@angular/core';
import { AdminService, AdminUser } from '../../core/services/admin.service';

@Component({
  selector: 'app-admin',
  templateUrl: './admin.component.html',
  styleUrls: ['./admin.component.scss']
})
export class AdminComponent implements OnInit {
  users: AdminUser[] = [];
  filteredUsers: AdminUser[] = [];
  loading = true;
  savingId: number | null = null;
  error = '';
  searchQuery = '';

  constructor(private adminService: AdminService) {}

  get adminCount(): number {
    return this.users.filter(user => user.role === 'admin').length;
  }

  ngOnInit(): void {
    this.loadUsers();
  }

  loadUsers(): void {
    this.loading = true;
    this.error = '';

    this.adminService.getUsers().subscribe({
      next: users => {
        this.users = users;
        this.applyFilter();
        this.loading = false;
      },
      error: () => {
        this.error = 'admin.loadError';
        this.loading = false;
      }
    });
  }

  applyFilter(): void {
    const query = this.searchQuery.trim().toLowerCase();

    if (!query) {
      this.filteredUsers = [...this.users];
      return;
    }

    this.filteredUsers = this.users.filter(user =>
      user.name.toLowerCase().includes(query) ||
      user.email.toLowerCase().includes(query) ||
      user.role.toLowerCase().includes(query)
    );
  }

  updateUser(user: AdminUser, changes: Partial<AdminUser>): void {
    this.savingId = user.id;
    this.adminService.updateUser(user.id, changes).subscribe({
      next: updatedUser => {
        this.replaceUser(updatedUser);
        this.savingId = null;
      },
      error: () => {
        this.error = 'admin.saveError';
        this.savingId = null;
      }
    });
  }

  deactivateUser(user: AdminUser): void {
    this.savingId = user.id;
    this.adminService.deactivateUser(user.id).subscribe({
      next: () => {
        this.replaceUser({ ...user, deleted_at: new Date().toISOString() });
        this.savingId = null;
      },
      error: () => {
        this.error = 'admin.saveError';
        this.savingId = null;
      }
    });
  }

  restoreUser(user: AdminUser): void {
    this.savingId = user.id;
    this.adminService.restoreUser(user.id).subscribe({
      next: updatedUser => {
        this.replaceUser(updatedUser);
        this.savingId = null;
      },
      error: () => {
        this.error = 'admin.saveError';
        this.savingId = null;
      }
    });
  }

  formatDate(value?: string | null): string {
    if (!value) {
      return '-';
    }

    return new Intl.DateTimeFormat('pt-PT', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    }).format(new Date(value));
  }

  private replaceUser(user: AdminUser): void {
    this.users = this.users.map(item => item.id === user.id ? user : item);
    this.applyFilter();
  }
}
